using CashFlow.Launch.Domain.Entities;using CashFlow.Launch.Domain.Entities.Base;using CashFlow.Launch.Domain.Interfaces;using Microsoft.EntityFrameworkCore;
namespace CashFlow.Launch.Infrastructure.Context;
public class CashFlowDbContext:DbContext{
readonly ITenantContext _tenant;public Guid CurrentGroupId=>_tenant.GroupId;
public CashFlowDbContext(DbContextOptions<CashFlowDbContext> options,ITenantContext tenant):base(options){_tenant=tenant;}
public DbSet<Entry> Entries=>Set<Entry>();public DbSet<OutboxMessage> OutboxMessages=>Set<OutboxMessage>();public DbSet<Account> Accounts=>Set<Account>();public DbSet<Category> Categories=>Set<Category>();public DbSet<RecurringEntry> RecurringEntries=>Set<RecurringEntry>();public DbSet<CreditCard> CreditCards=>Set<CreditCard>();public DbSet<CreditCardPurchase> CreditCardPurchases=>Set<CreditCardPurchase>();public DbSet<CreditCardInstallment> CreditCardInstallments=>Set<CreditCardInstallment>();public DbSet<MonthlyBudget> MonthlyBudgets=>Set<MonthlyBudget>();
protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<Entry>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);b.Entity<Account>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);b.Entity<Category>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);b.Entity<RecurringEntry>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);b.Entity<CreditCard>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);b.Entity<CreditCardPurchase>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);b.Entity<CreditCardInstallment>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);b.Entity<MonthlyBudget>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);b.Entity<OutboxMessage>().HasQueryFilter(x=>x.GroupId==CurrentGroupId);}
public override int SaveChanges(){ApplyTenant();return base.SaveChanges();}public override Task<int> SaveChangesAsync(CancellationToken ct=default){ApplyTenant();return base.SaveChangesAsync(ct);}void ApplyTenant(){if(!_tenant.HasGroup)throw new UnauthorizedAccessException("Grupo não identificado no token.");foreach(var e in ChangeTracker.Entries<Entity>().Where(x=>x.State==EntityState.Added)){e.Entity.GroupId=_tenant.GroupId;}}
}